module rocket_fuel_calculator (input clk,input rst_n,input start,input [15:0] payload,input [7:0] a [0:7],input [7:0] b [0:7],input [7:0] num_planets,output reg [31:0] result,output reg done,output reg error);reg [31:0] total_weight;reg [7:0] i;reg [2:0] state;reg [31:0] temp;reg [31:0] ratio;reg [7:0] current_a, current_b;reg [7:0] n_planets;parameter IDLE = 3'd0, PREPARE=3'd1, LOOP=3'd2, FINAL=3'd3, DONE=3'd4, ERROR=3'd5;always @(posedge clk or negedge rst_n) begin if (!rst_n) begin total_weight <= 0; i <=0; state <= IDLE; done <=0; error <=0; result <=0; end else begin case(state) IDLE: if(start) state <= PREPARE; else state <=IDLE; PREPARE: n_planets = num_planets; total_weight <= ({16'd0, payload} <<16); i <= n_planets -1; if (n_planets ==0) state <= FINAL; else state <= LOOP; LOOP: if (i <1) begin state <= FINAL; end else begin current_b = b[i]; if (current_b ==1) begin error <=1; state <= ERROR; end else begin ratio = (current_b <<16) / (current_b -1); temp = total_weight * ratio; temp >>>= 16; total_weight <= temp; current_a = a[i]; if (current_a ==1) begin error <=1; state <= ERROR; end else begin ratio = (current_a <<16) / (current_a -1); temp = total_weight * ratio; temp >>>=16; total_weight <= temp; end end i <= i -1; end FINAL: current_a = a[0]; if (current_a ==1) begin error <=1; state <= ERROR; end else begin ratio = (current_a <<16) / (current_a -1); temp = total_weight * ratio; temp >>>=16; total_weight <= temp; state <= DONE; end DONE: result <= total_weight - ({16'd0, payload} <<16); done <=1; ERROR: done <=1; error <=1; endcase end assign result = total_weight - ({16'd0, payload} <<16); assign done = state == DONE || state == ERROR; assign error = state == ERROR; endmodule